def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (after '+')
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = ''

        # Split pre-release (after '-')
        if '-' in version:
            main, prerelease = version.split('-', 1)
        else:
            main = version
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = main.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            # Convert identifiers: all-digit ones become (0, int), others become (1, str)
            prerelease_identifiers = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_identifiers.append((0, int(part)))
                else:
                    prerelease_identifiers.append((1, part))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(indexed_version):
        index, version = indexed_version
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting:
        # 1. Compare MAJOR, MINOR, PATCH numerically
        # 2. Version with no pre-release sorts after version with pre-release (for same MAJOR.MINOR.PATCH)
        # 3. Pre-release identifiers compared left to right
        # 4. All-digit identifiers sort before non-digit identifiers
        # 5. Fewer identifiers sort first (when all shared identifiers are equal)

        if prerelease_identifiers is None:
            # No pre-release: comes after versions with pre-release
            return (major, minor, patch, (1,), index)
        else:
            # Has pre-release: comes before versions without pre-release
            return (major, minor, patch, (0, tuple(prerelease_identifiers)), index)

    # Create list of (index, version) to maintain stable sort
    indexed_versions = list(enumerate(versions))
    # Sort by the sort key
    sorted_indexed = sorted(indexed_versions, key=sort_key)
    # Extract sorted versions
    return [version for _, version in sorted_indexed]

